This was indeed done with the assistance of LLMs but the change is smol (21 lines).

I think the filter function passed `registerDataObj` should run asynchronously, everything upstream should expect it to be asynchronous (i.e.: browser `fetch`) so it should not break anything.

```r
library(promises)
library(future)
plan(multisession) # Use background R processes

ui <- fluidPage(
  h3("Async registerDataObj Test"),
  tags$button(
    "Test Sync Endpoint",
    onclick = "fetch(syncUrl).then(r => r.json()).then(d => console.log('Sync:', d))"
  ),
  tags$button(
    "Test Async Endpoint",
    onclick = "fetch(asyncUrl).then(r => r.json()).then(d => console.log('Async:', d))"
  ),
  tags$script(HTML(
    "
    var syncUrl, asyncUrl;
    Shiny.addCustomMessageHandler('setUrls', function(urls) {
      syncUrl = urls.sync;
      asyncUrl = urls.async;
      console.log('URLs registered:', urls);
    });
  "
  ))
)

server <- function(input, output, session) {
  sync_url <- session$registerDataObj(
    "sync_data",
    list(msg = "Hello from sync!"),
    function(data, req) {
      cat("Sync endpoint hit!\n")
      httpResponse(200, "application/json", toJSON(data))
    }
  )

  async_url <- session$registerDataObj(
    "async_data",
    list(msg = "Hello from async!"),
    function(data, req) {
      cat("Async endpoint hit - starting future\n")
      future_promise({
        Sys.sleep(3) 
        data
      }) %...>%
        {
          cat("Async endpoint - future", local_i, "resolved!\n")
          httpResponse(200, "application/json", toJSON(.))
        }
    }
  )

  session$sendCustomMessage("setUrls", list(sync = sync_url, async = async_url))
}

shinyApp(ui, server)
```

