  output$plot1 <- renderPlot({
    ggplot(mtcars, aes(x=log(wt), y=mpg)) + geom_point()
  })

  output$info <- renderPrint({
    brushedPoints(mtcars, input$plot_brush, allRows = TRUE)
  })
}

shinyApp(ui, server)
