With the example app from rstudio/DT#369, if you select rows in the first datatable, and then add another table by moving the slider, the selected rows get unselected, with the current master.

```R
library(shiny)
library(DT)

numUI <- 0

ui <- shinyUI(fluidPage(
  mainPanel(
    sliderInput("number","Number of tables",1,10,1,1),
    tags$div(id="tables")
  )))

server <- shinyServer(function(input, output, session) {

  observe({
    if (input$number > numUI) {
      for (num in (numUI+1):input$number) {
        insertUI("#tables", "beforeEnd", DT::dataTableOutput(paste0("table", num)))
        output[[paste0("table",num)]] <- DT::renderDataTable(head(mtcars), server = FALSE)
      }
    }

    if (input$number < numUI) {
      for (num in (input$number+1):numUI) {
        removeUI(paste0("#table", num))
      }
    }

    numUI <<- input$number
  })

})
# Run the application
shinyApp(ui = ui, server = server)
```

After this change, the rows do not get unselected when adding a table.

Previously, if you wanted to modify (or add/remove) something in the `session$userData` environment from within a module, you had to do it in a roundabout way:

```r
library(shiny)

modUI <- function(id) {}
mod <- function(input, output, session) {
  ud <- session$userData
  ud$flag <- TRUE
}

ui <- fixedPage(
  modUI("modID")
)

server <- function(input, output, session) {
  callModule(mod, "modID")
  print(session$userData$flag)
}

shinyApp(ui, server)
```

With this PR, you can do it the normal/expected way:

```r
library(shiny)

modUI <- function(id) {}
mod <- function(input, output, session) {
  session$userData$flag <- TRUE
}

ui <- fixedPage(
  modUI("modID")
)

server <- function(input, output, session) {
  callModule(mod, "modID")
  print(session$userData$flag)
}

shinyApp(ui, server)
```

