## NEWS
- Added a series of JavaScript events:
  - `shiny:connected`: triggered when the initial connection to server is established
  - `shiny:disconnected`: session ended or connection lost
## Examples

``` r
library(shiny)
shinyApp(
  ui = fluidPage(
    tags$head(tags$script(HTML(
      "$(document).on('shiny:connected', function(event) {
        alert('socket state: ' + event.socket.readyState);
      });
      $(document).on('shiny:disconnected', function(event, data) {
        alert('socket state: ' + event.socket.readyState);
      });"
    ))),
    actionButton('foo', 'Stop')
  ),
  server = function(input, output) {
    observeEvent(input$foo, {
      stopApp()
    })
  }
)
